SELECT hn.id, hn.title, hn.summary, hn.cover, hn.create_time, (SELECT COUNT(*) FROM flow_index fi1 WHERE fi1.content_module='HEALTH_NEWS' AND fi1.content_id = hn.id AND fi1.type = 1) AS showCount, (SELECT COUNT(*) FROM flow_index fi1 WHERE fi1.content_module='HEALTH_NEWS' AND fi1.content_id = hn.id AND fi1.type = 2) AS viewCount, (SELECT COUNT(*) FROM flow_index fi1 WHERE fi1.content_module='HEALTH_NEWS' AND fi1.content_id = hn.id AND fi1.type = 3) AS upvoteCount, (SELECT COUNT(*) FROM flow_index fi1 WHERE fi1.content_module='HEALTH_NEWS' AND fi1.content_id = hn.id AND fi1.type = 4) AS collectionCount FROM health_news hn
AND hn.type_id = #{typeId}
AND hn.title LIKE concat('%',#{title},'%')
AND hn.create_time BETWEEN #{startTime} AND #{endTime}
AND hn.id IN
#{id}
ORDER BY
viewCount DESC
upvoteCount DESC
collectionCount DESC
viewCount DESC,upvoteCount DESC,collectionCount DESC
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM health_news hn


        AND hn.type_id = #{typeId}


        AND hn.title LIKE concat('%',#{title},'%')


